#include <cstdio>
#include <cstdlib>

// The C API being wrapped: begin() yields a nonnegative token or -1, and every
// successful token must be handed to end() exactly once.
int raw_mode_begin(int fd);
void raw_mode_end(int token);

class RawMode {
public:
    explicit RawMode(int fd) : token_(raw_mode_begin(fd)) {
        if (token_ < 0) {
            std::abort();  // Chapter 6 replaces this with structured reporting
        }
    }

    ~RawMode() { raw_mode_end(token_); }

    RawMode(const RawMode&) = delete;
    RawMode& operator=(const RawMode&) = delete;

    int token() const { return token_; }

private:
    int token_;
};

bool run_editor(int fd, const char* script) {
    RawMode mode{fd};

    if (script == nullptr) {
        return false;  // raw mode restored
    }
    if (script[0] == '\0') {
        return false;  // raw mode restored
    }
    if (std::fputs(script, stdout) < 0) {
        return false;  // raw mode restored
    }
    return mode.token() >= 0;  // raw mode restored
}

#include <cstddef>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t requested)
        : capacity_(round_up_pow2(requested)),
          mask_(capacity_ - 1),
          storage_(capacity_, 0) {}

    std::size_t capacity() const { return capacity_; }

    int& slot(std::size_t index) { return storage_[index & mask_]; }

private:
    // A static helper rather than a member, so the very first initializer
    // reads nothing that has not been initialized yet.
    static std::size_t round_up_pow2(std::size_t n) {
        std::size_t power = 1;
        while (power < n) {
            power *= 2;
        }
        return power;
    }

    // Members are initialized in *declaration* order, whatever order the
    // initializer list is written in. So declaration order has to be the
    // dependency order: mask_ reads capacity_, and storage_ reads capacity_.
    std::size_t capacity_;
    std::size_t mask_;
    std::vector<int> storage_;
};

#include <iostream>
#include <string>

std::string status_line() {
    return "build 4711 -- 3 warnings, 0 errors";
}

const std::string& longer(const std::string& a, const std::string& b) {
    return a.size() >= b.size() ? a : b;
}

void render() {
    // Direct binding of a temporary to a local const reference: the temporary
    // lives until the end of this scope, so both uses below are fine.
    const std::string& line = status_line();
    std::cout << line.size() << '\n';
    std::cout << line << '\n';

    // C++23 extends temporaries created in a range-for's range expression
    // through the loop, so this string dies only after the last iteration.
    int digits = 0;
    for (char c : status_line()) {
        if (c >= '0' && c <= '9') {
            ++digits;
        }
    }
    std::cout << digits << '\n';
}

void broken() {
    // Both temporaries bind to longer()'s parameters, which keeps them alive
    // for the call and no longer. Returning one of those references grants no
    // second extension, so both die at the semicolon on this line.
    const std::string& banner = longer(status_line(), std::string{"short"});
    // std::cout << banner << '\n';  // UB: banner dangles
    (void)banner;
}

#include <cstdint>

struct Deadline {
    std::uint16_t seconds;
    std::uint8_t retries;
};

struct JobSpec {
    Deadline deadline;
    int priority;
    double weight;
};

// Static storage duration: zero-initialized before any startup work runs, so
// every member is 0 without anyone writing an initializer. A block-scope
// `JobSpec s;` gets no such guarantee — its members are indeterminate, and
// reading one is undefined behavior.
JobSpec startup_default;

JobSpec from_priority(int priority) {
    return JobSpec{.deadline = {.seconds = 30, .retries = 3},
                   .priority = priority,
                   .weight = 1.0};
}

void examples() {
    // Value-initialization: every member is zero, nested aggregate included.
    JobSpec zeroed{};

    // Positional aggregate initialization, in declaration order. Swapping the
    // two Deadline fields still compiles: both are unsigned integers.
    JobSpec positional{{30, 3}, 5, 1.0};

    // Ill-formed: 300 is a constant expression that does not fit in
    // std::uint8_t, and braces reject the narrowing even one level down.
    // JobSpec narrowed{{30, 300}, 5, 1.0};

    (void)zeroed;
    (void)positional;
}

