// The naive version, which has a bug that a given link order may hide.
//
// registry.cpp:
//   std::vector<std::string> g_registry;
//
// flac.cpp:
//   struct Registrar { Registrar(const char* n) { g_registry.push_back(n); } };
//   Registrar flac_codec{"flac"};
//
// Rewrite so the order cannot matter.

writing.solution:
#include <cstddef>
#include <string>
#include <vector>

// Naive version: a namespace-scope `std::vector<std::string> g_registry;` in
// one translation unit, touched by a registrar's constructor in another. Within
// one translation unit dynamic initialization follows definition order, but
// across translation units the relative order is unspecified — the registrar
// may push into storage where no vector object has begun its lifetime.
//
// Here the registry is a function-local static, initialized the first time
// control reaches its declaration. Whichever registrar runs first constructs
// it, and it is fully alive before registry() returns.
std::vector<std::string>& registry() {
    static std::vector<std::string> names;
    return names;
}

class Registrar {
public:
    explicit Registrar(const char* name) { registry().push_back(name); }
};

// Each of these would normally live in its own translation unit. Their order
// relative to one another is still unspecified — but now that only permutes
// the contents, instead of touching an object that does not yet exist.
Registrar flac_codec{"flac"};
Registrar opus_codec{"opus"};

std::size_t codec_count() { return registry().size(); }

#include <iostream>

int depth = 0;

struct Policy {};

class Sampler {
public:
    explicit Sampler(Policy) : entered_(++depth) {}
    ~Sampler() { --depth; }

    Sampler(const Sampler&) = delete;
    Sampler& operator=(const Sampler&) = delete;

    int entered() const { return entered_; }

private:
    int entered_;
};

void probe() {
    // Braces cannot describe a parameter list, so this must be a definition.
    Sampler guard{Policy{}};
    std::cout << guard.entered() << '\n';

    // Declares a function named guard, taking one unnamed parameter of type
    // "Policy()" (adjusted to a pointer to function) and returning Sampler.
    // Nothing is constructed and depth never changes.
    // Sampler guard(Policy());

    // Declares a function named guard taking no arguments and returning
    // Sampler. Also not an object — and Sampler has no default constructor.
    // Sampler guard();
}
